local Audio = {}
local SOUND_SERVICE = game:GetService("SoundService")
Audio.__index = Audio

function Audio.new(...)
    local self = setmetatable({}, Audio)
    self:constructor(...)
    return self
end

function Audio:constructor(properties)
    self.Properties = properties
    self.Name = properties.Id
    self.Sounds = {}
    self.Is3D = properties.Is3D
end

function Audio:CreateSound()
    local properties = self.Properties
    local sound = Instance.new("Sound")
    sound.Name = properties.Id
    sound.SoundId = type(properties.SoundId) == "string" and properties.SoundId
        or "rbxassetid://" .. tostring(properties.SoundId)
    sound.RollOffMaxDistance = properties.RollOffMaxDistance
    sound.RollOffMinDistance = properties.RollOffMinDistance
    sound.PlaybackRegionsEnabled = properties.PlaybackRegionsEnabled
    sound.PlaybackSpeed = properties.PlaybackSpeed
    sound.TimePosition = properties.TimePosition
    sound.Volume = properties.Volume
    sound.SoundGroup = SOUND_SERVICE:FindFirstChild(properties.SoundGroup)
    return sound
end

function Audio:RecycleOnEnded(sound: Sound)
    local connection
    connection = sound.Ended:Connect(function()
        local parent = sound.Parent
        
        sound.Parent = nil
        table.insert(self.Sounds, sound)
        connection:Disconnect()
        connection = nil

        if parent and parent.Name == "_sound" then
            parent:Destroy()
        end
    end)
end

function Audio:GetSound()
    local sound = self.Sounds[1]
    if not sound then
        sound = self:CreateSound()
    end
    return sound
end

function Audio:GetSoundId()
    return self.Properties.Id
end

return Audio